        { type: 'order', q: 'Расставь планеты земной группы от самой маленькой к самой большой.', items: ['Меркурий', 'Марс', 'Венера', 'Земля'], why: 'Меркурий — самый маленький, Марс почти вдвое меньше Земли, а Венера чуть меньше Земли.' },
        { type: 'one', q: 'У какой планеты земной группы больше всего спутников?', a: ['У Земли', 'У Венеры', 'У Меркурия', 'У Марса'], c: 3, why: 'У Марса два маленьких спутника — Фобос и Деймос. У Земли один — Луна, а у Меркурия и Венеры спутников нет совсем.' },
        { type: 'sort', q: 'Меркурий или Венера?', groups: ['Меркурий', 'Венера'], items: [['Ближе всех к Солнцу', 0], ['Самая горячая планета', 1], ['Ночью мороз около −180 °C', 0], ['Толстые облака углекислого газа', 1], ['Ярче всех планет на вечернем небе', 1], ['Год — 88 суток', 0]], why: 'Меркурий — ближайший и безвоздушный, Венера — горячая, облачная и очень яркая.' },
        { type: 'case', story: 'Вечером после заката Мурлок увидел низко на западе очень яркую «звезду». Она светит ровно и почти не мерцает, а через час опускается за горизонт.', q: 'Кто это, скорее всего?', a: [{ t: 'Планета Венера', ok: true, why: 'Верно! Венера — «вечерняя звезда»: яркая, ровная, видна после заката на западе.' }, { t: 'Полярная звезда', ok: false, why: 'Полярная — на севере, не такая яркая и почти не двигается.' }, { t: 'Самолёт', ok: 'mid', why: 'Проверить стоит, но у самолёта мигают огоньки, и он быстро летит по небу.' }, { t: 'Летающая тарелка', ok: false, why: 'Сыщик ищет простое объяснение: это Венера.' }], why: 'Яркое ровное светило на западе после заката — Венера.' }
